{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-grid.json
    A section with a heading and the features as a grid of cards or tiles, or as rows with a picture. Icons are Lucide names. Axes: layout (grid, rows), columns, item (card, tile, cell: bordered tile with a round icon), media side (rows), density, tone.
    Props (p): id, title, features, action, layout, cols, item, mediaSide, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_features = ($p['features'] ?? null)}
{var $v_action = ($p['action'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_item = ($p['item'] ?? 'card')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if ui_t(ui_eq($v_item, 'cell'))}
  {capture $c_4}
    {capture $c_3}
      {capture $c_1}
        {=ui_text($v_title)}
      {/capture}
      {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(2), 'Size' => 'sm', 'Weight' => 'semibold', 'Class' => 'leading-7', 'Attrs' => ui_attrs(['id', ui_add($v_id, '-title')])], 'children' => $c_1])|noescape}
      {if ui_t(ui_get($v_action, ['label']))}
        {capture $c_2}
          {=ui_text(ui_get($v_action, ['label']))}
        {/capture}
        {=ui_include('ui/link/link.latte', ['p' => ['Href' => ui_s(ui_coalesce([ui_get($v_action, ['href']), '#/'])), 'Variant' => 'default', 'Class' => ui_s(ui_cnv([ui_preset('blocks/presets/defaults.json', ['text', 'tiny']), 'shrink-0 font-medium leading-5'])), 'Attrs' => ui_attrs(['data-testid', 'section-action'])], 'children' => $c_2])|noescape}
      {/if}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Justify' => 'between', 'Class' => 'w-full'], 'children' => $c_3])|noescape}
    {=ui_include('blocks/feature-cards.latte', ['p' => ['features' => $v_features, 'cols' => $v_cols, 'item' => $v_item]])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'tone' => $v_tone, 'density' => $v_density, 'measure' => 'fill', 'className' => ui_cnv(['py-0']), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_4])|noescape}
{else}
  {capture $c_5}
    {if ui_t(ui_eq($v_layout, 'rows'))}
      {=ui_include('blocks/feature-rows.latte', ['p' => ['features' => $v_features, 'mediaSide' => $v_mediaSide]])|noescape}
    {else}
      {=ui_include('blocks/feature-cards.latte', ['p' => ['features' => $v_features, 'cols' => $v_cols, 'item' => $v_item]])|noescape}
    {/if}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'action' => $v_action, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_5])|noescape}
{/if}
